# CP24 full-cohort Step 2 reconstructed CD8 differentiation feature extraction.
rm(list=ls());source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","reconstructed_panel_framework.R"));rp_install_and_load(c("dplyr","readr","stringr","tibble","purrr"),"flowCore");source(file.path(sd_repo_root(),"R","panels","CP24","MANIFEST_RECONSTRUCTED.R"))
a<-sd_analysis_dir("CP24");r<-file.path(a,"11_RData");out<-file.path(a,"02_feature_extraction");td<-file.path(a,"03_thresholds");dir.create(out,recursive=TRUE,showWarnings=FALSE);dir.create(td,recursive=TRUE,showWarnings=FALSE);load(file.path(r,"SDY2583_CP24_STEP1_inventory_RECONSTRUCTED.RData"));th<-CP24_MANIFEST$thresholds;readr::write_csv(tibble::tibble(marker=names(th),threshold=as.numeric(th)),file.path(td,"SDY2583_CP24_thresholds_RECONSTRUCTED.csv"))
extract_one<-function(path,thresholds=th){tryCatch({obj<-rp_read_transform(path);map<-obj$marker_map;ex<-flowCore::exprs(obj$ff);ch<-c(CD3=rp_find_channel(map,c("^CD3$"),"BV605-A"),CD8=rp_find_channel(map,c("^CD8$"),"PerCP-Cy5-5-A"),CD62L=rp_find_channel(map,c("CD62L"),"BV650-A"),CD95=rp_find_channel(map,c("CD95"),"BV711-A"),CD57=rp_find_channel(map,c("^CD57$"),"BV786-A"),CD27=rp_find_channel(map,c("^CD27$"),"BB515-A"),CX3CR1=rp_find_channel(map,c("CX3CR1"),"PE-A"),PD1=rp_find_channel(map,c("PD-?1"),"PE-CF594-A"),CD45RA=rp_find_channel(map,c("CD45RA"),"PE-Cy5-A"),CXCR3=rp_find_channel(map,c("CXCR3"),"BV421-A"),CXCR5=rp_find_channel(map,c("CXCR5"),"PE-Cy7-A"));if(any(is.na(ch)))stop("Missing CP24 markers: ",paste(names(ch)[is.na(ch)],collapse=", "));v<-lapply(ch,function(x)rp_vec(ex,x));cd3<-v$CD3>thresholds["CD3"];cd8<-v$CD8>thresholds["CD8"];gate<-cd3&cd8;ra<-v$CD45RA>thresholds["CD45RA"];l62<-v$CD62L>thresholds["CD62L"];cd27<-v$CD27>thresholds["CD27"];cd57<-v$CD57>thresholds["CD57"];cx3<-v$CX3CR1>thresholds["CX3CR1"];cd95<-v$CD95>thresholds["CD95"];pd1<-v$PD1>thresholds["PD1"];pd1h<-v$PD1>thresholds["PD1_HIGH"];naive<-ra&l62;tcm<-!ra&l62;tem<-!ra&!l62;temra<-ra&!l62;temra_neg<-temra&!cd27
 tibble::tibble(subject_id=rp_extract_subject_id(path),result_file_name=basename(path),feature_ok=TRUE,error_message=NA_character_,total_events=nrow(ex),n_cd3_pos=rp_n(cd3),n_cd8_pos=rp_n(cd8),n_cd3_cd8_pos=rp_n(gate),pct_cd3_pos_total=rp_pct(cd3),pct_cd8_pos_total=rp_pct(cd8),pct_cd3_cd8_pos_total=rp_pct(gate),pct_cd8_within_cd3=rp_pct(cd8,cd3),median_CD62L_in_CD3CD8=rp_median(v$CD62L[gate]),median_CD27_in_CD3CD8=rp_median(v$CD27[gate]),median_PD1_in_CD3CD8=rp_median(v$PD1[gate]),median_CD57_in_CD3CD8=rp_median(v$CD57[gate]),median_CX3CR1_in_CD3CD8=rp_median(v$CX3CR1[gate]),median_CD95_in_CD3CD8=rp_median(v$CD95[gate]),median_CD45RA_in_CD3CD8=rp_median(v$CD45RA[gate]),median_CXCR3_in_CD3CD8=rp_median(v$CXCR3[gate]),median_CXCR5_in_CD3CD8=rp_median(v$CXCR5[gate]),pct_naive_like=rp_pct(naive,gate),pct_tcm_like=rp_pct(tcm,gate),pct_tem_like=rp_pct(tem,gate),pct_temra_like=rp_pct(temra,gate),pct_cd62l_pos_within_cd3cd8=rp_pct(l62,gate),pct_cd62l_neg_within_cd3cd8=rp_pct(!l62,gate),pct_cd45ra_pos_within_cd3cd8=rp_pct(ra,gate),pct_cd45ra_neg_within_cd3cd8=rp_pct(!ra,gate),pct_cd27_pos_within_cd3cd8=rp_pct(cd27,gate),pct_cd27_neg_within_cd3cd8=rp_pct(!cd27,gate),pct_temra_cd27neg=rp_pct(temra_neg,gate),pct_temra_cd27pos=rp_pct(temra&cd27,gate),pct_cd62lneg_cd27neg=rp_pct(!l62&!cd27,gate),pct_cd45ra_pos_cd62lneg_cd27neg=rp_pct(ra&!l62&!cd27,gate),pct_naive_cd27pos=rp_pct(naive&cd27,gate),pct_naive_cd27neg=rp_pct(naive&!cd27,gate),pct_cd57_pos=rp_pct(cd57,gate),pct_cx3cr1_pos=rp_pct(cx3,gate),pct_cd95_pos=rp_pct(cd95,gate),pct_cd57_cx3cr1_pos=rp_pct(cd57&cx3,gate),pct_cd57_cd95_pos=rp_pct(cd57&cd95,gate),pct_cx3cr1_cd95_pos=rp_pct(cx3&cd95,gate),pct_cd57_cx3cr1_cd95_pos=rp_pct(cd57&cx3&cd95,gate),pct_pd1_pos=rp_pct(pd1,gate),pct_pd1_high=rp_pct(pd1h,gate),pct_pd1_temra=rp_pct(pd1&temra,gate),pct_pd1_temra_cd27neg=rp_pct(pd1&temra_neg,gate),pct_pd1_cd57_pos=rp_pct(pd1&cd57,gate),pct_pd1_cx3cr1_pos=rp_pct(pd1&cx3,gate),pct_pd1_cd95_pos=rp_pct(pd1&cd95,gate),pct_pd1_cd57_cx3cr1_cd95_pos=rp_pct(pd1&cd57&cx3&cd95,gate),pct_pd1_pos_within_temra=rp_pct(pd1,gate&temra),pct_pd1_pos_within_temra_cd27neg=rp_pct(pd1,gate&temra_neg))},error=function(e)tibble::tibble(subject_id=rp_extract_subject_id(path),result_file_name=basename(path),feature_ok=FALSE,error_message=conditionMessage(e),total_events=NA_integer_,n_cd3_pos=NA_integer_,n_cd8_pos=NA_integer_,n_cd3_cd8_pos=NA_integer_))}
feature_table<-purrr::map_dfr(fcs_files,extract_one);summary<-tibble::tibble(n_files=nrow(feature_table),n_subjects=dplyr::n_distinct(feature_table$subject_id),n_success=sum(feature_table$feature_ok),n_failed=sum(!feature_table$feature_ok),median_total_events=median(feature_table$total_events,na.rm=TRUE),median_cd3_cd8_events=median(feature_table$n_cd3_cd8_pos,na.rm=TRUE),n_ge500=sum(feature_table$n_cd3_cd8_pos>=500,na.rm=TRUE),n_ge1000=sum(feature_table$n_cd3_cd8_pos>=1000,na.rm=TRUE));readr::write_csv(feature_table,file.path(out,"SDY2583_CP24_FULL_850_feature_table_RECONSTRUCTED.csv"));readr::write_csv(summary,file.path(out,"SDY2583_CP24_feature_extraction_summary_RECONSTRUCTED.csv"));save(feature_table,summary,th,extract_one,file=file.path(r,"SDY2583_CP24_STEP2_feature_extraction_RECONSTRUCTED.RData"));print(summary)
